package com.bank.pricing;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RpnEvaluatorDemo {

    private static final Logger log = Logger.getLogger(RpnEvaluatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FeeFormulaEvaluator evaluator = new FeeFormulaEvaluator();

        // Postfix for: (10000 * 0.02) + 50  =>  base 2% fee plus flat 50
        String[] formula = {"10000", "0.02", "*", "50", "+"};

        BigDecimal fee = evaluator.evaluate(formula);
        log.info(() -> "Computed fee: " + fee);   // 250.00
    }
}

