class FeeFormulaEvaluator {

    private static final Logger log = Logger.getLogger(FeeFormulaEvaluator.class.getName());

    BigDecimal evaluate(String[] tokens) {
        java.util.Deque<BigDecimal> stack = new java.util.ArrayDeque<>();
        for (String token : tokens) {
            if (isOperator(token)) {
                BigDecimal right = stack.pop();   // second operand popped first
                BigDecimal left = stack.pop();    // first operand popped second
                BigDecimal result = apply(left, right, token);
                stack.push(result);
                log.fine(() -> "  " + left + " " + token + " " + right + " = " + result);
            } else {
                BigDecimal value = new BigDecimal(token);
                stack.push(value);
                log.fine(() -> "  push " + value);
            }
        }
        return stack.pop();                       // last value = answer
    }

    private boolean isOperator(String t) {
        return t.equals("+") || t.equals("-") || t.equals("*") || t.equals("/");
    }

    private BigDecimal apply(BigDecimal l, BigDecimal r, String op) {
        return switch (op) {
            case "+" -> l.add(r);
            case "-" -> l.subtract(r);
            case "*" -> l.multiply(r);
            case "/" -> l.divide(r, 2, java.math.RoundingMode.HALF_UP);
            default -> throw new IllegalArgumentException("Unknown operator " + op);
        };
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
